INSERT INTO TradeType (TT_ID, TT_NAME, TT_IS_SELL, TT_IS_MRKT) SELECT CAST(TradeType.TT_ID AS TEXT) AS TT_ID, CAST(TradeType.TT_NAME AS TEXT) AS TT_NAME, CAST(COALESCE(TRY_CAST(TT_IS_SELL AS DECIMAL(1, 0)), 0) AS DECIMAL(1, 0)) AS TT_IS_SELL, CAST(COALESCE(TRY_CAST(TT_IS_MRKT AS DECIMAL(1, 0)), 0) AS DECIMAL(1, 0)) AS TT_IS_MRKT FROM Source.TradeType;
